 await p.goto(base+'/'+route(c));await p.locator('.cp-pace-controls').waitFor();await p.waitForFunction(()=>!document.querySelector('[data-practice-next]').disabled);const root=p.locator('[data-exercise-id]'),id=await root.getAttribute('data-exercise-id');await root.locator('h3').focus();await p.keyboard.press('Space');await p.waitForFunction(()=>window.ended.length>0);await p.waitForFunction(()=>!document.querySelector('[data-practice-next]').disabled);
